"""Render a self-contained, safe HTML presentation from actual run checkpoints."""
from __future__ import annotations
import argparse, html, json, sqlite3
from datetime import datetime, timezone
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
RATE = {'L4': .000222 + 4 * .0000131 + 16 * .00000222,
        'H100!': .001097 + 4 * .0000131 + 16 * .00000222}

def snapshot(waves):
    c = sqlite3.connect(f'file:{ROOT / "message_signatures/messages.sqlite"}?mode=ro', uri=True)
    c.execute('BEGIN')
    active = json.loads(c.execute("SELECT value FROM metadata WHERE key='active_run'").fetchone()[0])
    run = active['id']
    progress = json.loads(c.execute("SELECT value FROM metadata WHERE key='progress'").fetchone()[0])
    total = c.execute('SELECT count(*) FROM messages').fetchone()[0]
    unique = c.execute('SELECT count(DISTINCT text_hash) FROM messages').fetchone()[0]
    predictions = c.execute('SELECT count(*) FROM predictions WHERE run_id=?', (run,)).fetchone()[0]
    annotated = c.execute('SELECT count(*) FROM messages m JOIN predictions p ON m.text_hash=p.text_hash WHERE p.run_id=?', (run,)).fetchone()[0]
    labels = [{'act':r[0], 'count':r[1], 'review':r[2]} for r in c.execute('SELECT label,count(*),sum(needs_review) FROM predictions WHERE run_id=? GROUP BY label ORDER BY count(*) DESC',(run,))]
    review, truncated = c.execute('SELECT sum(needs_review),sum(truncated) FROM predictions WHERE run_id=?',(run,)).fetchone()
    c.close()
    checkpoints = []
    for p in waves:
        p = Path(p)
        if not p.is_file(): continue
        d = json.loads(p.read_text())
        perf = d.get('performance', {})
        elapsed = d.get('elapsedSeconds', 0)
        gpu = d.get('gpuTypeRequested', 'L4')
        checkpoints.append({'id': d['exportId'], 'gpu': gpu, 'pairBatch': d.get('pairBatchSize'),
            'finishedShards':d['completedShardCount'], 'selectedShards':d['selectedShardCount'],
            'finishedUnique':sum(s['count'] for s in d['shards']), 'partialUnique':sum(s['count'] for s in d.get('partialShards', [])),
            'elapsedSeconds':elapsed, 'inferenceSeconds':perf.get('inferenceSeconds'),
            'errors':len(d.get('errors', [])), 'complete':d['complete'],
            'computeCeilingEstimateUSD':round(8 * (elapsed + 20) * RATE[gpu], 3),
            'resultsManifestSha256':d['resultsManifestSha256']})
    parity = {}
    for name in ('h100','l4','l4-128'):
        p=ROOT / f'message_signatures/modal-parity-{name}.json'
        if p.exists():
            d=json.loads(p.read_text()); q=d['comparison']
            parity[name]={'sample':q['messageCount'],'maxDelta':q['maxAbsScoreDelta'],
                'topAgreement':q['topLabelAgreement'],'reviewAgreement':q['reviewAgreement'],
                'truncationAgreement':q['truncationAgreement'],'recommendation':d['recommendation']}
    return {'generatedAt':datetime.now(timezone.utc).isoformat(),'runId':run,
        'state':progress['state'],'sourceMessages':total,'uniqueTexts':unique,
        'annotatedSourceMessages':annotated,'uniquePredictions':predictions,
        'remainingUnique':unique-predictions,'reviewUnique':review or 0,'truncatedUnique':truncated or 0,
        'sourceSha256':active['source_sha256'],'modelSha256':active['model_sha256'],
        'taxonomySha256':active['taxonomy_sha256'],'labels':labels,'waves':checkpoints,
        'experiment':json.loads((ROOT/'message_signatures/context-experiment-summary.json').read_text()),
        'costLedger':json.loads((ROOT/'message_signatures/modal-cost-ledger.json').read_text()),
        'parity':parity,'budgetUSD':10,'costStatus':'Conservative configured-resource estimates; not reconciled Modal billing',
        'pilotReserveUSD':.20,'completedWaveCeilingEstimateUSD':round(sum(w['computeCeilingEstimateUSD'] for w in checkpoints),3)}

CSS = '''
:root{--paper:#f4f0e5;--ink:#253b32;--muted:#627367;--line:#cbd0bf;--green:#315d49;--light:#e1eadc;--amber:#f0dfaf;--accent:#bd623b}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.55 system-ui,-apple-system,sans-serif}button,a{color:inherit}button{font:inherit}a{text-underline-offset:4px}.shell{max-width:1500px;margin:auto;padding:30px 48px 24px}.mast{display:flex;justify-content:space-between;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--line);gap:20px}.brand{font-size:14px;font-weight:750;letter-spacing:.1em;text-transform:uppercase}.tag{font-size:12px;border:1px solid var(--line);border-radius:30px;padding:7px 13px;white-space:nowrap}.slide{min-height:690px;padding:50px 0 35px}.eyebrow{text-transform:uppercase;letter-spacing:.17em;color:var(--green);font-size:12px;font-weight:750;margin:0 0 22px}h1,h2,h3{font-family:Georgia,serif;font-weight:400;letter-spacing:-.04em;line-height:1.08}h1{font-size:clamp(56px,6.5vw,96px);margin:0 0 26px}h2{font-size:clamp(40px,4.5vw,65px);margin:0 0 30px}h3{font-size:32px;margin:0 0 15px}.lede{max-width:770px;font-size:22px;line-height:1.6;color:var(--muted)}.grid{display:grid;grid-template-columns:1.25fr 1fr;gap:55px;align-items:start}.dark{background:var(--green);color:var(--paper);padding:34px;border-radius:5px}.dark .eyebrow{color:#dbe7d5}.big{font:64px/1 Georgia,serif;letter-spacing:-.05em;margin-bottom:18px}.small{font-size:13px;color:var(--muted)}.dark .small{color:#d4dfce}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:34px 0}.stat{border-top:2px solid var(--green);padding-top:18px}.stat strong{display:block;font:42px/1.1 Georgia,serif;letter-spacing:-.03em}.stat span{font-size:13px;color:var(--muted)}.pill{display:inline-block;padding:7px 12px;background:var(--light);font-size:13px;border-radius:30px}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:34px 0}.step{padding:25px;border:1px solid var(--line);border-radius:5px}.num{display:block;font:30px/1 Georgia,serif;color:var(--accent);margin-bottom:20px}.step b{display:block;margin-bottom:12px}.note{border-left:3px solid var(--accent);padding:15px 22px;background:#efe6d1;font-size:15px;margin-top:26px}.plot{padding:28px;background:#faf8f1;border:1px solid var(--line);border-radius:5px}.barrow{margin:20px 0}.barlabel{display:flex;justify-content:space-between;gap:12px;font-size:14px;margin-bottom:8px}.bar{height:19px;border-radius:3px;background:var(--green);min-width:3px}.h100{background:#8a9e84}.track{background:#e3e5d9;border-radius:3px}table{width:100%;border-collapse:collapse;margin:24px 0;font-size:15px}th{text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}td,th{padding:15px 10px 15px 0;border-bottom:1px solid var(--line);vertical-align:top}.mono{font:12px/1.5 ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere}.hash{padding:16px 0;border-bottom:1px solid var(--line)}.hash b{display:block;font-size:12px;text-transform:uppercase;color:var(--muted);margin-bottom:6px}.footer{display:flex;align-items:center;gap:20px;border-top:1px solid var(--line);padding-top:18px}.footer button{background:none;border:1px solid var(--green);border-radius:30px;padding:9px 18px;cursor:pointer}.footer button:hover{background:var(--light)}.footer button:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.footer button:disabled{opacity:.35;cursor:default}.count{margin:auto;font-size:13px;letter-spacing:.08em;color:var(--muted)}.print{margin-left:auto;font-size:13px}.hidden{display:none}.complete{background:var(--light)}.budget{display:flex;align-items:baseline;gap:10px}.budget strong{font:80px/1 Georgia,serif}.budget span{font-size:18px}.rule{border-top:1px solid var(--line);margin:25px 0}.list{padding-left:20px;color:var(--muted)}li{margin-bottom:14px}.snapshot{font-size:12px;color:var(--muted);margin-top:20px}.two{display:grid;grid-template-columns:1fr 1fr;gap:30px}.value{font:40px/1.1 Georgia,serif;display:block;margin-bottom:10px}@media(max-width:800px){.shell{padding:22px}.slide{padding-top:35px;min-height:0}.grid,.two{grid-template-columns:1fr;gap:25px}.flow{grid-template-columns:1fr 1fr}.stats{gap:15px}.stat strong{font-size:31px}.lede{font-size:19px}.big{font-size:55px}.mast{align-items:start}.brand{max-width:210px}table{font-size:12px}.footer{margin-top:30px;gap:10px}.footer button{padding:8px 12px}.print{display:none}}@media(prefers-reduced-motion:no-preference){.slide{animation:enter .2s ease-out}@keyframes enter{from{opacity:.7;transform:translateY(5px)}to{opacity:1;transform:none}}}@media print{body{font-size:13px;background:white}.shell{padding:0;max-width:none}.mast,.footer,.snapshot{display:none}.slide,.slide.hidden{display:block;min-height:0;break-after:page;padding:30px}.slide:last-of-type{break-after:auto}h1{font-size:64px}h2{font-size:45px}.dark{print-color-adjust:exact}.flow{gap:10px}.step{padding:16px}.grid{gap:30px}}
'''

def render(d):
    e=html.escape; n=lambda v:f'{v:,}'; complete=d['remainingUnique']==0
    status='Complete' if complete else 'Continuation in progress'
    waves=''.join(f'<tr><td>Wave {i+1}<br><span class="small">{e(w["gpu"])} · batch {w["pairBatch"]}</span></td><td>{n(w["finishedUnique"])}</td><td>{w["finishedShards"]} / {w["selectedShards"]}</td><td>{w["elapsedSeconds"]/60:.1f} min</td><td>≤ ${w["computeCeilingEstimateUSD"]:.2f}*</td></tr>' for i,w in enumerate(d['waves']))
    maxlabel=max((r['count'] for r in d['labels']),default=1)
    bars=''.join(f'<div class="barrow"><div class="barlabel"><span>{e(r["act"].replace("_"," "))}</span><b>{n(r["count"])}</b></div><div class="track"><div class="bar" style="width:{100*r["count"]/maxlabel:.2f}%"></div></div></div>' for r in d['labels'][:7])
    hashes=''.join(f'<div class="hash"><b>{label}</b><span class="mono">{e(d[key])}</span></div>' for label,key in [('Logical run','runId'),('Source SHA-256','sourceSha256'),('Model SHA-256','modelSha256'),('Taxonomy SHA-256','taxonomySha256')])
    slides=[f'''<div class="grid"><div><p class="eyebrow">01 / The run</p><h1>A village of messages.<br>One small model.</h1><p class="lede">Classifying the work each message proposes to do—and attaching a reusable DSPy-style signature skeleton.</p><div class="stats"><div class="stat"><strong>{n(d['sourceMessages'])}</strong><span>source chat records</span></div><div class="stat"><strong>{n(d['uniqueTexts'])}</strong><span>distinct message texts</span></div><div class="stat"><strong>12</strong><span>candidate communicative acts</span></div></div></div><aside class="dark"><p class="eyebrow">Current checkpoint</p><div class="big">{n(d['annotatedSourceMessages'])}</div><p>source messages classified</p><div class="rule"></div><p>{n(d['remainingUnique'])} unique texts remain.</p><span class="tag">{status}</span><p class="small">The figures are a saved snapshot. This file has no network dependencies or live polling.</p></aside></div>''',
    f'''<p class="eyebrow">02 / What we actually ran</p><h2>Inference, with a frozen model.</h2><div class="grid"><div><p class="lede">DeBERTa-v3 base zero-shot classifier<br><b>184,423,682 parameters · FP16 · 512 tokens</b></p><p>Every text is paired with twelve authored hypotheses. The model returns one entailment score per hypothesis. We retain the leading candidate, alternatives, review flags, and truncation details.</p><div class="pill">Weights are not updated</div></div><aside class="plot"><h3>DSPy-style output</h3><p><code>message → candidate act → signature skeleton</code></p><p class="small">The signature is a proposed template. Its slots have not been extracted or executed. This run does not distill or train a new model.</p></aside></div><div class="flow"><div class="step"><span class="num">1</span><b>Deduplicate</b>Exact text hashes share a prediction.</div><div class="step"><span class="num">2</span><b>Score</b>Twelve independent entailment pairs.</div><div class="step"><span class="num">3</span><b>Review</b>Weak scores, narrow margins, and truncated messages.</div><div class="step"><span class="num">4</span><b>Attach</b>Proposed reusable signature templates.</div></div>''',
    '''<p class="eyebrow">03 / Why Modal</p><h2>Rent GPU time.<br>Return completed shards.</h2><div class="grid"><div><p class="lede">Up to eight L4 GPU containers process independent shards in parallel.</p><p>Modal starts containers for the function calls and scales them down afterward. There is no permanent GPU server or always-on inference endpoint.</p><ul class="list"><li>Only pending exact texts are sent for scoring.</li><li>Model and tokenizer files live in a private Modal Volume.</li><li>Each completed shard is saved atomically before import.</li><li>Ten-minute waves and an app watchdog bound the compute budget.</li></ul></div><aside class="dark"><p class="eyebrow">Operational choices</p><h3>Small batches.<br>Durable checkpoints.</h3><p>The first full wave hit memory limits on some L4 batches. The continuation uses 128 pairs per batch and 500-text shards.</p><p class="small">Completed outputs are kept. Unfinished shards are retried from the remaining-text index.</p></aside></div>''',
    '''<p class="eyebrow">04 / Measured pilots</p><h2>Faster versus cheaper.</h2><div class="grid"><div class="plot"><div class="barrow"><div class="barlabel"><span>H100</span><b>40.0 texts / second</b></div><div class="track"><div class="bar h100" style="width:100%"></div></div></div><div class="barrow"><div class="barlabel"><span>L4</span><b>12.8 texts / second</b></div><div class="track"><div class="bar" style="width:31.9%"></div></div></div><p class="small">68-message pilot; inference time excludes model loading. This sample is not a sustained full-corpus throughput guarantee.</p></div><div><p class="lede">L4 was about 18% cheaper per message after configured CPU and memory costs.</p><p>Both GPU pilots matched the local baseline on all 68 leading labels, review flags, and truncation outcomes. Maximum absolute score differences were below 0.004.</p><div class="note">Parity checks the migration. It does not prove that the model’s classifications are correct.</div></div></div>''',
    f'''<p class="eyebrow">05 / Durable work</p><h2>Completed work survives<br>the next wave.</h2><table><thead><tr><th>Wave</th><th>Complete outputs</th><th>Finished shards</th><th>Wall time</th><th>Compute estimate</th></tr></thead><tbody>{waves or '<tr><td colspan="5">First wave running.</td></tr>'}</tbody></table><div class="two"><div><span class="value">{n(d['uniquePredictions'])}</span>unique predictions imported<div class="rule"></div><p class="small">Cloud imports validate the source, model, tokenizer, taxonomy, scores, hashes, counts, and execution provenance. Existing local predictions are preserved.</p></div><div><span class="value">{n(d['remainingUnique'])}</span>unique texts still pending<div class="rule"></div><p class="small">Partial shards are not counted as complete predictions. The next export contains only text hashes absent from the database.</p></div></div><p class="small">*Conservative configured-resource estimate, including a small shutdown allowance; not reconciled Modal billing.</p>''',
    f'''<p class="eyebrow">06 / Model proposals</p><h2>What the classifier suggests.</h2><div class="grid"><div class="plot">{bars}</div><div><p class="lede">{n(d['reviewUnique'])} unique predictions are flagged for review.</p><p>{n(d['truncatedUnique'])} inputs were truncated under the fixed 512-token policy.</p><div class="note">These are counts of model proposals among imported results. The twelve scores are independent, uncalibrated probabilities. The labels are not verified facts about the village.</div><p class="small">A single leading act can oversimplify a message that performs several kinds of work. Context and segmentation need separate evaluation.</p></div></div>''',
    f'''<p class="eyebrow">07 / Budget and provenance</p><h2>Reproducible.<br>Within a $10 compute cap.</h2><div class="grid"><div><div class="budget"><strong>$10</strong><span>maximum Modal budget</span></div><p>No automatic retries, paid endpoint, or subscription upgrade. App-level deadlines limit queued work.</p><p>The conservative configured-resource ceiling is <b>${d['costLedger']['conservativeEstimatedCeilingUSD']:.2f}</b>, including pilots, both full waves, both experiments, and an overhead reserve. All GPU apps are stopped.</p><p class="small">Estimates use <a href="https://modal.com/pricing">Modal’s published per-second rates</a>, four configured CPU cores, and a 16 GiB memory ceiling. Billing reconciliation is unavailable from the captured CLI data.</p></div><aside>{hashes}</aside></div>''',
    f'''<p class="eyebrow">08 / What comes next</p><h2>{'The archive is classified.' if complete else 'Finish the pending archive.'}</h2><div class="grid"><div><p class="lede">{'Every unique source text now has a prediction. Review remains essential.' if complete else 'The remaining work runs on Modal L4 GPUs. Local model jobs are stopped and subagents are paused.'}</p><p>The full snapshot is published in the private <a href="https://huggingface.co/datasets/maujim/ai-village-analysis">Hugging Face dataset</a>. All source records have predictions. The next step is human review of representative uncertain classifications.</p></div><aside class="plot"><h3>One experiment, completed</h3><p>Does real nearby conversation context change the proposed act more than approximately length-matched shuffled context?</p><p class="small">Two L4 trials scored 768 inputs across 128 short target messages. No experiment inputs were truncated.</p></aside></div><div class="note">Saved checkpoint · {e(d['generatedAt'])}<br>Use the arrow keys or the controls below to present. Print produces a page for each slide.</div>''']
    x=d['experiment']; changes=x['labelChanges']['matchedFraming']
    slides.append(f'''<p class="eyebrow">09 / Context sensitivity</p><h2>Context changes the label.<br>Even when shuffled.</h2><div class="stats"><div class="stat"><strong>{changes['real_context']} / {x['targetCount']}</strong><span>changed with nearby context</span></div><div class="stat"><strong>{changes['shuffled_context']} / {x['targetCount']}</strong><span>changed with shuffled context</span></div><div class="stat"><strong>{x['wrapperOnlyLabelChanges']} / {x['targetCount']}</strong><span>changed from the wrapper alone</span></div></div><div class="grid"><div><p class="lede">The classifier scores the entire premise. Adding a conversation window can obscure the act of the target message.</p><p>Two trials used the same targets and context selections. The second trial matched the empty-context wrapper across all conditions to control for framing.</p></div><aside class="plot"><h3>A better next question</h3><p>Can a target-aware extraction step use the context while keeping its attention on the current message?</p><div class="note">These results measure sensitivity, not accuracy. No human truth labels were collected. The sample contains only short messages, with one model and one seed.</div></aside></div>''')
    content=''.join(f'<section class="slide{(" hidden" if i else "")}" aria-label="Slide {i+1}" aria-hidden="{str(bool(i)).lower()}">{s}</section>' for i,s in enumerate(slides))
    data=json.dumps(d,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    script='''const slides=Array.from(document.querySelectorAll('.slide'));let current=0;const prev=document.getElementById('prev'),next=document.getElementById('next'),count=document.getElementById('count');function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>{s.classList.toggle('hidden',j!==current);s.setAttribute('aria-hidden',String(j!==current));});prev.disabled=current===0;next.disabled=current===slides.length-1;count.textContent=String(current+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');}prev.addEventListener('click',()=>show(current-1));next.addEventListener('click',()=>show(current+1));document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(current+(e.key==='ArrowRight'?1:-1));}});document.getElementById('print').addEventListener('click',()=>window.print());show(0);'''
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AI Village · The inference run</title><style>{CSS}</style></head><body><main class="shell"><header class="mast"><div class="brand">AI Village / Run notes</div><span class="tag">{status} · standalone presentation</span></header>{content}<nav class="footer" aria-label="Presentation controls"><button id="prev" type="button" aria-label="Previous slide">← Previous</button><span id="count" class="count" aria-live="polite"></span><button id="next" type="button" aria-label="Next slide">Next →</button><button id="print" class="print" type="button">Print / Save PDF</button></nav><p class="snapshot">Snapshot {e(d["generatedAt"])} · No live polling · Pretrained model inference · Source: <a href="https://huggingface.co/datasets/aidigestorg/ai-village">AI Digest / AI Village</a></p></main><script id="run-data" type="application/json">{data}</script><script>{script}</script></body></html>'

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--wave',action='append',default=[])
    p.add_argument('--output',type=Path,default=ROOT/'run.html')
    a=p.parse_args();d=snapshot(a.wave)
    a.output.write_text(render(d),encoding='utf-8')
    (ROOT/'message_signatures/modal-run-summary.json').write_text(json.dumps(d,indent=2)+'\n')
    print(json.dumps({'output':str(a.output),'remainingUnique':d['remainingUnique'],'state':d['state']}))
if __name__=='__main__': main()
